using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned metadata for: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {personInfo!.Type.Name}");

// No resolver → returns false instead of throwing
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
if (!empty.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person> returned false — no metadata available");

public record Person(string Name, int Age);
```

**Key APIs (new in .NET 11):**

| Method | Returns | Throws on miss? |
|--------|---------|-----------------|
| `options.GetTypeInfo<T>()` | `JsonTypeInfo<T>` | ✅ Yes |
| `options.TryGetTypeInfo<T>(out ...)` | `bool` | ❌ No |

Use `GetTypeInfo<T>()` when you're confident metadata exists; use `TryGetTypeInfo<T>()` to branch safely without try/catch.
